from h import *
A = dict(id="A", levels=L1, kind="Web page", source="Fennline Trains website", title="Fennline Trains", body=[
 {"p": "Home | Tickets | Timetables | Railcards | Contact us"},
 {"p": "Welcome to Fennline Trains. We run fast, friendly services between Fennbridge, Kettlewick and Ashby Cross every day of the week. Tickets can be bought online, at the station or on board."},
 {"p": "Travelling with a bike? Bikes travel free on all our trains, except between 7:00 am and 9:30 am on weekdays, when the trains are at their busiest."},
 {"p": "Need some help with your journey? Please speak to a member of staff at any station. They will be glad to help."}])
B = dict(id="B", levels=L1, kind="Newspaper article", source="The Vale Gazette", title="Park and Ride: is it worth it?", body=[
 {"p": "Kettlewick's new Park and Ride opened in March, and thousands of drivers have already tried it. Local people have given it a warm welcome. The idea is simple. Drivers leave their cars at the edge of town and take a bus into the centre, which takes about ten minutes."},
 {"h": "How it works"},
 {"p": "The car park has 600 spaces and parking costs £3 for the whole day. A bus leaves every eight minutes from 6:30 am until 7:00 pm. Parking also covers your bus fare, so there is nothing more to pay. The car park is lit at night so that drivers feel safe, and staff are on duty all day to help."},
 {"h": "Who is it for?"},
 {"p": "Commuters and shoppers are the biggest users, and shoppers like it too. \"I used to spend half an hour driving round looking for a space,\" says Imran Shah, who works in a bank in the town centre. \"Now I park, read my book on the bus, and I'm at my desk before nine.\""},
 {"h": "What does it cost?"},
 {"p": "Parking in the town centre can cost up to £9 for a day, so the Park and Ride is much cheaper. Regular users can save even more with a season ticket (a ticket that lets you travel as often as you like for a month or a year). The council says the scheme will pay for itself within five years."},
 {"h": "Is it perfect?"},
 {"p": "Not quite. Some passengers complain that the buses are full during the morning peak, when many people are travelling to work or school. A council spokesperson said that extra buses will be added if they are needed."},
 {"p": "Even so, it is the best idea the council has had for years. If you drive into town every day, you should try it."}])
C = dict(id="C", levels=L1, kind="Email", source="Email between friends", title="Subject: Park and Ride report!", body=[
 {"p": "Hi Jess,"},
 {"p": "Guess what? I tried the new Park and Ride in Kettlewick on Saturday and it was loads better than I expected. Parking was only £3, which is a bargain compared with the £9 I paid in town last month. The bus turned up after about two minutes and the driver was really friendly."},
 {"p": "The downside? We went at 8:15 and the bus was rammed, so I had to stand all the way into town (it only took ten minutes, thankfully). The ride itself was lovely. There was Wi-Fi on the bus, so I caught up on my messages, and the seats were really comfy. Also, the last bus back is at 7:00 pm, which is far too early if you fancy a night out!"},
 {"p": "My tips if you go:"},
 {"ul": ["Get there before eight, so you can get a seat.", "Keep your ticket safe, because you need it for the bus home.", "Check the last bus time before you leave the car park.", "Take a coat. The bus stop is miles from the entrance!"]},
 {"p": "Honestly, I'd choose it over driving every time. Let me know if you try it. Can't wait to hear what you think!"},
 {"p": "Maya"}])

